import * as THREE from 'three';
import {createAvatar} from './avatar-character-factory.js';
import {AvatarMotionEngine} from './avatar-motion-engine.js';
const CONFIGS={avatarGirl:{kind:'girl',glasses:true,skin:0xe4a17c,hair:0x171319,lip:0xb85158,iris:0x322821,outfit:0x356f58}};let active=null;
function dispose(){if(!active)return;cancelAnimationFrame(active.frame);removeEventListener('resize',active.resize);active.motion.destroy();active.scene.traverse(object=>{object.geometry?.dispose?.();if(Array.isArray(object.material))object.material.forEach(value=>value.dispose?.());else object.material?.dispose?.();});active.renderer.dispose();delete window.__avatarDebug;active=null;}
function addAtmosphere(scene,config){const count=70,positions=new Float32Array(count*3);for(let index=0;index<count;index++){positions[index*3]=(Math.random()-.5)*9;positions[index*3+1]=(Math.random()-.4)*6;positions[index*3+2]=-1-Math.random()*4;}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));const points=new THREE.Points(geometry,new THREE.PointsMaterial({color:config.kind==='girl'?0xe7c67d:0x9fa9de,size:.035,transparent:true,opacity:.52}));scene.add(points);return points;}
function floor(scene,config){const value=new THREE.Mesh(new THREE.CircleGeometry(2.2,48),new THREE.ShadowMaterial({color:config.kind==='girl'?0x365d4d:0x22263a,opacity:.2}));value.rotation.x=-Math.PI/2;value.position.y=-1.64;value.receiveShadow=true;scene.add(value);return value;}
function start(id){const stage=document.querySelector('[data-avatar-stage]'),canvas=document.querySelector('#avatar-theme-canvas'),config=CONFIGS[id];if(!stage||!canvas||!config)return;if(active?.canvas===canvas)return;dispose();const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(31,1,.1,50);if(new URLSearchParams(location.search).has('avatarCapture'))scene.background=new THREE.Color(0xdfe9d9);camera.position.set(0,.65,7.25);camera.lookAt(0,.65,0);const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;scene.add(new THREE.HemisphereLight(config.kind==='girl'?0xffecd7:0xdde4ff,0x252132,2.1));const key=new THREE.DirectionalLight(config.kind==='girl'?0xffd8b5:0xcdd6ff,3.6);key.position.set(-3,4,5);key.castShadow=true;scene.add(key);const rim=new THREE.DirectionalLight(config.kind==='girl'?0xa9d8b8:0x8d7ac8,2.5);rim.position.set(4,2,-2);scene.add(rim);const rig=createAvatar(config);scene.add(rig.root);const motion=new AvatarMotionEngine(rig,stage),particles=addAtmosphere(scene,config),ground=floor(scene,config);stage.addEventListener('click',event=>{if(Math.abs(event.movementX||0)<3)motion.trigger('greet')});const clock=new THREE.Clock(),resize=()=>{if(!active||!stage.isConnected)return;const rect=stage.getBoundingClientRect();camera.aspect=Math.max(1,rect.width)/Math.max(1,rect.height);camera.updateProjectionMatrix();renderer.setSize(Math.max(1,rect.width),Math.max(1,rect.height),false)},frame=()=>{if(!active||!stage.isConnected||document.body.dataset.theme!==id){dispose();return}const dt=Math.min(.04,clock.getDelta());motion.update(dt);particles.rotation.y+=dt*.018;particles.position.y=Math.sin(clock.elapsedTime*.3)*.08;renderer.render(scene,camera);active.frame=requestAnimationFrame(frame)};active={id,canvas,scene,camera,renderer,rig,motion,particles,ground,resize,frame:0};window.__avatarDebug={id,get headYaw(){return rig.head.rotation.y},get bodyYaw(){return rig.root.rotation.y}};addEventListener('resize',resize);resize();stage.querySelector('[data-avatar-loading]')?.setAttribute('hidden','');frame();}
window.startAvatarTheme=start;window.stopAvatarTheme=dispose;const current=document.body?.dataset.theme;if(CONFIGS[current])start(current);
